<?php
require 'config.php';
require_role(['Management', 'Supervisor', 'Administrator']);

function read_report_xlsx_metadata($path)
{
	$jsonPath = preg_replace('/\.xlsx$/i', '.json', $path);
	if (file_exists($jsonPath)) {
		$meta = json_decode(file_get_contents($jsonPath), true);
		if (is_array($meta)) {
			return [
				'Branch' => $meta['branch'] ?? 'Main Store',
				'Period' => $meta['period'] ?? 'N/A',
				'Generated By' => $meta['generated_by'] ?? 'Supervisor',
				'Generated At' => $meta['generated_at'] ?? date('Y-m-d H:i:s')
			];
		}
	}
	if (!class_exists('ZipArchive')) {
		return [];
	}

	$archive = new ZipArchive();
	if ($archive->open($path) !== true) {
		return [];
	}

	$sheetXml = $archive->getFromName('xl/worksheets/sheet1.xml');
	$sharedStringsXml = $archive->getFromName('xl/sharedStrings.xml');
	$archive->close();
	if (!is_string($sheetXml)) {
		return [];
	}

	$previousLibxmlSetting = libxml_use_internal_errors(true);
	$sheetDocument = new DOMDocument();
	$loaded = $sheetDocument->loadXML($sheetXml, LIBXML_NONET);
	$sharedStrings = [];
	if ($loaded && is_string($sharedStringsXml)) {
		$sharedDocument = new DOMDocument();
		if ($sharedDocument->loadXML($sharedStringsXml, LIBXML_NONET)) {
			$sharedXPath = new DOMXPath($sharedDocument);
			$sharedXPath->registerNamespace('x', 'http://schemas.openxmlformats.org/spreadsheetml/2006/main');
			foreach ($sharedXPath->query('//x:si') as $sharedItem) {
				$text = '';
				foreach ($sharedXPath->query('.//x:t', $sharedItem) as $textNode) {
					$text .= $textNode->textContent;
				}
				$sharedStrings[] = $text;
			}
		}
	}
	libxml_clear_errors();
	libxml_use_internal_errors($previousLibxmlSetting);
	if (!$loaded) {
		return [];
	}

	$xpath = new DOMXPath($sheetDocument);
	$xpath->registerNamespace('x', 'http://schemas.openxmlformats.org/spreadsheetml/2006/main');
	$metadata = [];
	foreach ($xpath->query('//x:sheetData/x:row') as $row) {
		$cells = [];
		foreach ($xpath->query('./x:c', $row) as $cell) {
			$reference = strtoupper($cell->getAttribute('r'));
			if (!preg_match('/^([A-Z]+)\d+$/', $reference, $matches)) {
				continue;
			}

			$value = '';
			if ($cell->getAttribute('t') === 'inlineStr') {
				foreach ($xpath->query('./x:is//x:t', $cell) as $textNode) {
					$value .= $textNode->textContent;
				}
			} else {
				$valueNode = $xpath->query('./x:v', $cell)->item(0);
				$value = $valueNode ? $valueNode->textContent : '';
				if ($cell->getAttribute('t') === 's') {
					$value = $sharedStrings[(int) $value] ?? '';
				}
			}
			$cells[$matches[1]] = $value;
		}

		if (isset($cells['A'], $cells['B']) && in_array($cells['A'], ['Branch', 'Period', 'Generated By', 'Generated At'], true)) {
			$metadata[$cells['A']] = $cells['B'];
		}
	}

	return $metadata;
}

if (isset($_GET['delete'])) {
	$delete_file = basename($_GET['delete']);
	$target = __DIR__ . '/reports/generated/' . $delete_file;
	if (is_file($target)) {
		unlink($target);
		$jsonTarget = preg_replace('/\.xlsx$/i', '.json', $target);
		if (is_file($jsonTarget)) unlink($jsonTarget);
		audit('Delete Generated Report', 'reports', null, 'Deleted generated report file ' . $delete_file);
	}
	header('Location: management_reports.php');
	exit;
}

$report_dir = __DIR__ . '/reports/generated';
$report_files = is_dir($report_dir) ? glob($report_dir . '/*') : [];
usort($report_files, function ($a, $b) {
	return filemtime($b) <=> filemtime($a);
});

$reports = [];
$seen_files = [];
foreach ($report_files as $report_path) {
	if (!is_file($report_path)) {
		continue;
	}

	$file_name = basename($report_path);
	$ext = strtolower(pathinfo($file_name, PATHINFO_EXTENSION));
	if ($ext !== 'xlsx') {
		continue;
	}

	$base_name = preg_replace('/\.xlsx$/i', '', $file_name);
	if (isset($seen_files[$base_name])) {
		continue;
	}
	$seen_files[$base_name] = true;

	$branch = 'Unknown Branch';
	$period = 'N/A';
	$generated_by = 'Supervisor';
	$generated_at = date('Y-m-d H:i:s', filemtime($report_path));

	if (preg_match('/([A-Za-z0-9-]+)-\d{8}-\d{6}$/', $base_name, $matches)) {
		$branch = str_replace('-', ' ', ucwords(str_replace('-', ' ', $matches[1])));
	}
	if (preg_match('/(\d{8})-(\d{6})$/', $base_name, $matches)) {
		$date_part = $matches[1];
		$generated_at = substr($date_part, 0, 4) . '-' . substr($date_part, 4, 2) . '-' . substr($date_part, 6, 2) . ' ' . substr($matches[2], 0, 2) . ':' . substr($matches[2], 2, 2) . ':' . substr($matches[2], 4, 2);
	}

	$metadata = read_report_xlsx_metadata($report_path);
	$branch = $metadata['Branch'] ?? $branch;
	$period = $metadata['Period'] ?? $period;
	$generated_by = $metadata['Generated By'] ?? $generated_by;
	$generated_at = $metadata['Generated At'] ?? $generated_at;

	$reports[] = [
		'branch' => $branch,
		'period' => $period,
		'generated_by' => $generated_by,
		'generated_at' => $generated_at,
		'file' => $file_name,
		'file_type' => $ext,
	];
}

include 'partials/header.php';
?>
<div class="page-head">
	<div>
		<h2>Management Report Review</h2>
	</div>
</div>
<section class="card">
	<div class="section-head">
		<h3>Shared Branch Reports</h3>
		<span class="muted"><?= count($reports) ?> report(s)</span>
	</div>
	<div class="table-wrap">
		<table>
			<thead>
				<tr><th>Branch</th><th>Period</th><th>Generated By</th><th>Generated At</th><th>File</th><th>Action</th></tr>
			</thead>
			<tbody>
				<?php if ($reports): ?>
					<?php foreach ($reports as $report): ?>
						<tr>
							<td><?= e($report['branch']) ?></td>
							<td><?= e($report['period']) ?></td>
							<td><?= e($report['generated_by']) ?></td>
							<td><?= e(date('M d, Y h:i A', strtotime($report['generated_at']))) ?></td>
							<td><?= e($report['file']) ?></td>
							<td>
								<a class="btn secondary" href="reports/generated/<?= rawurlencode($report['file']) ?>" target="_blank" rel="noopener">Download <?= strtoupper($report['file_type'] ?? 'FILE') ?></a>
								<a class="btn danger-btn" href="management_reports.php?delete=<?= rawurlencode($report['file']) ?>" onclick="return confirm('Delete this report file?');">Delete</a>
							</td>
						</tr>
					<?php endforeach; ?>
				<?php else: ?>
					<tr>
						<td colspan="6" class="muted">No static reports have been generated yet.</td>
					</tr>
				<?php endif; ?>
			</tbody>
		</table>
	</div>
</section>
<?php include 'partials/footer.php'; ?>
